<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\StockApiAllowedIp;use Illuminate\Http\Request;
class StockApiAllowedIpController extends Controller {public function index(){return view('admin.masterdata.stock-api-access.index',['ips'=>StockApiAllowedIp::orderByDesc('is_active')->orderBy('ip_address')->get()]);}public function store(Request$r){$d=$r->validate(['ip_address'=>['required','ip','unique:stock_api_allowed_ips,ip_address'],'label'=>['nullable','string','max:150']]);StockApiAllowedIp::create([...$d,'is_active'=>true]);return back()->with('success','IP ditambahkan.');}public function update(Request$r,StockApiAllowedIp $stockApiAllowedIp){$d=$r->validate(['label'=>['nullable','string','max:150'],'is_active'=>['required','boolean']]);$stockApiAllowedIp->update($d);return back()->with('success','Status diperbarui.');}public function destroy(StockApiAllowedIp $stockApiAllowedIp){$stockApiAllowedIp->delete();return back()->with('success','IP dihapus.');}}
